function renderCreatorImportPreview(){const rows=state.creatorImport.rows,existing=new Set(state.creatorImport.existing.map(account=>`${String(account.platform||'Instagram').toLowerCase()}|${String(account.handle||'').replace(/^@/,'').toLowerCase()}`)),seen=new Set(),mode=state.creatorImport.mode;let valid=0,duplicates=0,errors=0;const preview=rows.map(row=>{const key=importKey(row);let action=row.error?'Error':existing.has(key)?mode==='update'?'Update':'Skip':seen.has(key)?'Duplicate in file':'Create';seen.add(key);if(action==='Create'||action==='Update')valid++;else if(action==='Skip'||action==='Duplicate in file')duplicates++;else errors++;return{...row,action}});$('#creatorImportSummary').innerHTML=rows.length?`<span class="badge">${rows.length} rows</span><span class="badge green">${valid} ready</span><span class="badge amber">${duplicates} skipped</span>${errors?`<span class="badge rose">${errors} errors</span>`:''}`:'Choose a CSV to preview.';$('#creatorImportPreview').innerHTML=preview.length?`<table><thead><tr><th>Row</th><th>Handle</th><th>Name</th><th>Tier</th><th>Dog size</th><th>Action</th></tr></thead><tbody>${preview.slice(0,200).map(row=>`<tr><td>${row.row}</td><td>@${esc(row.account.handle)}</td><td>${esc(row.creator.display_name)}</td><td>${esc(row.creator.tier||'—')}</td><td>${esc(row.creator.dog_size||'—')}</td><td class="${row.action==='Error'?'import-error':''}">${esc(row.error||row.action)}</td></tr>`).join('')}</tbody></table>${preview.length>200?`<p class="muted">Showing the first 200 of ${preview.length} rows.</p>`:''}`:'';$('#confirmCreatorImportBtn').disabled=!valid}
async function confirmCreatorImport(){const button=$('#confirmCreatorImportBtn'),seen=new Set(),uniqueRows=[];let fileDuplicates=0;for(const row of state.creatorImport.rows){const key=importKey(row);if(key&&seen.has(key)){fileDuplicates++;continue}seen.add(key);uniqueRows.push(row)}const action=await runAction(button,'Importing creators',()=>importCreators(uniqueRows,state.creatorImport.mode),{inlineError:false,buttonText:'Importing…',afterSuccess:async()=>{state.creatorPage=1;await loadCreators()}});if(!action.ok)return;const result=action.value;result.skipped+=fileDuplicates;if(result.errors.length){$('#creatorImportSummary').innerHTML=`<span class="badge green">${result.created} created</span><span class="badge">${result.updated} updated</span><span class="badge amber">${result.skipped} skipped</span><span class="badge rose">${result.errors.length} failed</span>`;$('#creatorImportPreview').innerHTML=`<div class="form-error" role="alert"><strong>Some rows were not imported.</strong><ul>${result.errors.slice(0,100).map(item=>`<li>Row ${esc(item.row||'—')}: ${esc(item.message)}</li>`).join('')}</ul>${result.errors.length>100?`<p>Showing the first 100 of ${result.errors.length} errors.</p>`:''}</div>`;button.disabled=true;toast('Import completed with errors. Review the failed rows.');return}$('#creatorImportDialog').close();toast(`Imported ${result.created} · updated ${result.updated} · skipped ${result.skipped}.`)}
function downloadCreatorTemplate(){const sample=['matchmate_creator','https://www.instagram.com/matchmate_creator/','Creator Name','Instagram','A','Human + Pet','Human + Pet','Medium','3500','New York, NY','Strong','Benchmark brand','Wild One','creator@example.com','Clean lifestyle content'];downloadText('matchmate-creator-import-template.csv',[CREATOR_TEMPLATE.join(','),sample.map(csvCell).join(',')].join('\n'),'text/csv;charset=utf-8')}
