async function renderCreatorDrawer(editing=false){if(state.drawer?.type!=='creator')return;clearDraftGuard();const renderToken=++state.request.drawerRender,c=state.drawer.record,expectedId=c.id,expectedTab=state.drawerTab,subtitle=[c.creator_code,c.created_at?`Added ${date(c.created_at)}`:''].filter(Boolean).join(' · '),tabs=editing?[['profile','Profile']]:[['profile','Profile'],['accounts','Accounts & Pets'],['outreach','Outreach'],['collaborations','Collaborations']];openDrawer('Creator',c.display_name||c.nickname||'New creator',subtitle);renderTabs(tabs,state.drawerTab,tab=>{state.drawerTab=tab;renderCreatorDrawer(editing)});const body=$('#drawerBody');body.innerHTML='<div class="empty-state">Loading…</div>';$('#drawerFooter').innerHTML='';try{if(state.drawerTab==='profile')body.innerHTML=creatorProfileForm(c,editing);else if(state.drawerTab==='accounts')await renderCreatorRelations(c.id,body);else if(state.drawerTab==='outreach')await renderOutreach(c.id,body);else await renderCreatorCollaborations(c.id,body);if(renderToken!==state.request.drawerRender||!activeDrawer('creator',expectedId,expectedTab))return;renderDrawerFooter(c,editing,'creator');bindDrawerForms();if(editing&&state.drawerTab==='profile')beginDraftGuard('creator profile',body)}catch(error){if(renderToken===state.request.drawerRender&&activeDrawer('creator',expectedId,expectedTab)){body.innerHTML='<div class="empty-state">Unable to load this section.</div>';handleError(error)}}}
function creatorProfileForm(c,editing){if(editing&&!c.id)return`<div class="drawer-section"><h3>Add creator</h3><p class="muted">Start with the Instagram account. The CRM will create the creator profile, primary account and a Not Contacted outreach record together.</p><div class="form-grid">${field('instagram_handle','Instagram Handle',c.instagram_handle,editing,'text',true)}${field('display_name','Display Name (optional)',c.display_name,editing)}${field('instagram_profile_url','Instagram Profile URL (optional)',c.instagram_profile_url,editing,'url')}${selectField('owner_id','Owner (optional)',state.refs.owners.map(x=>[x.id,x.name]),c.owner_id,editing)}</div></div>`;return`<div class="drawer-section"><h3>Core identity</h3>${c.created_at?`<p class="muted">Added ${date(c.created_at)}. This date is assigned automatically and cannot be edited.</p>`:''}<div class="form-grid">${field('display_name','Display Name',c.display_name,editing)}${field('nickname','Preferred Name',c.nickname,editing)}${field('legal_name','Legal Name',c.legal_name,editing)}${field('contact_email','Email',c.contact_email,editing,'email')}${field('contact_phone','Phone',c.contact_phone,editing)}${selectField('tier','Tier',TIERS,c.tier,editing)}${selectField('fit_verdict','Fit Verdict',FIT_VERDICTS,c.fit_verdict,editing)}${selectField('account_type','Account Type',ACCOUNT_TYPES,c.account_type,editing)}${selectField('dog_size','Dog Size',DOG_SIZES,c.dog_size,editing)}${selectField('relationship_status','Relationship',RELATIONSHIPS,c.relationship_status,editing)}${selectField('owner_id','Owner',state.refs.owners.map(x=>[x.id,x.name]),c.owner_id,editing)}${field('location','Location',c.location,editing)}${field('tags','Tags',Array.isArray(c.tags)?c.tags.join(', '):c.tags,editing)}${textarea('fit_notes','Fit Notes',c.fit_notes,editing)}${textarea('notes','Notes',c.notes,editing)}${textarea('database_notes','Database Notes',c.database_notes,editing)}</div></div>`}
async function renderCreatorRelations(id,body){if(!id)return body.innerHTML='<div class="empty-state">Save the creator before adding accounts, pets or addresses.</div>';const[accounts,pets,addresses]=await Promise.all([related('creator_accounts','creator_id',id),related('creator_pets','creator_id',id),related('creator_addresses','creator_id',id)]);if(!activeDrawer('creator',id,'accounts'))return;body.innerHTML=creatorRelationSection('creator_accounts','Social Accounts',accounts,row=>`${row.platform}: @${row.handle}`,row=>row.profile_url)+creatorRelationSection('creator_pets','Pets',pets,row=>`${row.name||'Pet'} · ${row.breed||'Unknown breed'}`,row=>`${row.size||''} ${row.neck_size_cm?`· ${row.neck_size_cm} cm neck`:''}`)+creatorRelationSection('creator_addresses','Addresses',addresses,row=>row.label||'Address',row=>row.full_address);for(const[table,rows]of[['creator_accounts',accounts],['creator_pets',pets],['creator_addresses',addresses]]){$$(`[data-add-creator-related="${table}"]`).forEach(button=>button.addEventListener('click',()=>openCreatorRelationEditor(table,{})));$$(`[data-edit-creator-related="${table}"]`).forEach(button=>button.addEventListener('click',()=>openCreatorRelationEditor(table,rows.find(row=>row.id===button.dataset.id)||{})))}}
