function openCreatorRelationEditor(table,record){const title={creator_accounts:'Social Account',creator_pets:'Pet',creator_addresses:'Address'}[table],body=$('#drawerBody');clearDraftGuard();$('#drawerFooter').innerHTML='';body.innerHTML=`<div class="drawer-section"><div class="section-head"><h3>${record.id?'Edit':'Add'} ${title}</h3><button id="cancelCreatorRelated" class="secondary compact" type="button">Cancel</button></div><div id="creatorRelatedForm" class="form-grid">${creatorRelationFields(table,record)}</div><div class="editor-actions"><button id="saveCreatorRelated" type="button">Save ${title}</button>${record.id?'<button id="archiveCreatorRelated" class="secondary" type="button">Archive</button>':''}</div></div>`;$('#cancelCreatorRelated').addEventListener('click',()=>discardChangesThen(()=>renderCreatorDrawer()));$('#saveCreatorRelated').addEventListener('click',()=>saveCreatorRelation(table,record,title));const archiveButton=$('#archiveCreatorRelated');archiveButton?.addEventListener('click',async()=>{if(!confirm(`Archive this ${title.toLowerCase()}?`))return;const result=await runAction(archiveButton,`Archiving ${title.toLowerCase()}`,async()=>{await archive(table,record.id);return logActivitySafely({entityType:table,entityId:record.id,creatorId:state.drawer.record.id,action:'Archived',before:record})},{buttonText:'Archiving…',afterSuccess:()=>renderCreatorDrawer()});if(!result.ok)return;toast(result.value?`${title} archived. Activity history could not be recorded.`:`${title} archived.`)});beginDraftGuard(title.toLowerCase(),$('#creatorRelatedForm'))}
