async function saveCreatorRelation(table,before,title){const button=$('#saveCreatorRelated'),payload=Object.fromEntries(FormDataLike($('#creatorRelatedForm')));for(const key of ['followers','engagement_rate','neck_size_cm','weight_kg'])if(payload[key]!=='')payload[key]=Number(payload[key]);for(const key of ['is_primary','is_default'])if(key in payload)payload[key]=payload[key]==='true';const creator=state.drawer.record,result=await runAction(button,`Saving ${title.toLowerCase()}`,async()=>{const saved=await save(table,{...before,...payload,creator_id:creator.id,owner_id:creator.owner_id||null}),activityWarning=await logActivitySafely({entityType:table,entityId:saved.id,creatorId:creator.id,action:before.id?'Updated':'Created',before:before.id?before:null,after:saved});return{saved,activityWarning}},{afterSuccess:()=>renderCreatorDrawer()});if(!result.ok)return;toast(result.value.activityWarning?'Saved. Activity history could not be recorded.':'Saved.')}
async function renderOutreach(id,body){if(!id)return body.innerHTML='<div class="empty-state">Save the creator first.</div>';const rows=await related('outreach_records','creator_id',id);if(!activeDrawer('creator',id,'outreach'))return;body.innerHTML=`<div class="drawer-section"><div class="section-head"><h3>Outreach history</h3><button id="addOutreachBtn" class="secondary compact" type="button">Add touch</button></div>${rows.length?rows.map(row=>`<article class="related-item"><div><strong>${esc(row.status)}</strong><p>${esc(row.channel||'')} · ${date(row.last_contact_at)}</p><p>${esc(row.notes||'')}</p></div></article>`).join(''):'<div class="empty-state">No outreach recorded.</div>'}</div>`;$('#addOutreachBtn')?.addEventListener('click',()=>openOutreachEditor(id))}
async function renderCreatorCollaborations(id,body){if(!id)return body.innerHTML='<div class="empty-state">Save the creator first.</div>';const rows=await related('collaborations','creator_id',id);if(!activeDrawer('creator',id,'collaborations'))return;body.innerHTML=`<div class="drawer-section"><div class="section-head"><h3>Collaboration history</h3><button id="convertCreatorBtn" class="compact" type="button">Create confirmed collaboration</button></div>${rows.length?rows.map(row=>`<article class="related-item"><div><strong>${esc(row.collaboration_code||shortId(row.id,'CO'))}</strong><p><span class="badge ${badgeClass(row.stage)}">${esc(row.stage)}</span> · ${date(row.start_date)}</p></div><button class="secondary compact" data-open-collab="${row.id}">Open</button></article>`).join(''):'<div class="empty-state">No collaboration. Create one only after the creator explicitly agrees.</div>'}</div>`;const convertButton=$('#convertCreatorBtn');convertButton?.addEventListener('click',async()=>{if(!confirm('Create a collaboration only after the creator has explicitly agreed. Has this creator confirmed the collaboration?'))return;const result=await runAction(convertButton,'Creating confirmed collaboration',()=>createCollaborationFromOutreach(id,state.drawer.record.owner_id),{buttonText:'Creating…',afterSuccess:()=>renderCreatorDrawer()});if(!result.ok)return;toast('Confirmed collaboration created.')});$$('[data-open-collab]').forEach(button=>button.addEventListener('click',()=>openCollaboration(button.dataset.openCollab)))}
function renderDrawerFooter(record,editing,type){const footer=$('#drawerFooter');if(editing)footer.innerHTML=`<button class="secondary cancel-edit" type="button">Cancel</button><button class="save-record" type="button">${record.id?'Save changes':type==='creator'?'Add creator':'Create collaboration'}</button>`;else if(type==='collaboration')footer.innerHTML=`<button class="secondary edit-record" type="button">Edit</button>${record.stage==='Closed'?`<button class="danger-button delete-erroneous" type="button">Delete erroneous record</button>`:`<button class="danger-button cancel-collaboration" type="button">Cancel collaboration</button>`}`;else footer.innerHTML=`<button class="secondary edit-record" type="button">Edit</button><button class="secondary archive-record" type="button">Archive</button>`;$('.edit-record',footer)?.addEventListener('click',()=>discardChangesThen(()=>type==='creator'?openCreatorEditor(record):openCollaborationEditor(record)));$('.cancel-edit',footer)?.addEventListener('click',()=>discardChangesThen(()=>type==='creator'?(record.id?openCreator(record.id):closeDrawer(true)):record.id?openCollaboration(record.id):closeDrawer(true)));$('.save-record',footer)?.addEventListener('click',()=>saveDrawer(type));const cancelButton=$('.cancel-collaboration',footer),deleteButton=$('.delete-erroneous',footer),archiveButton=$('.archive-record',footer);cancelButton?.addEventListener('click',()=>cancelCollaborationRecord(record,cancelButton));deleteButton?.addEventListener('click',()=>deleteErroneousRecord(record.id,deleteButton));archiveButton?.addEventListener('click',async()=>{if(!confirm('Archive this creator? It can be restored from the database.'))return;if(!confirmDiscardChanges())return;const result=await runAction(archiveButton,'Archiving creator',()=>archive('creators',record.id),{buttonText:'Archiving…',afterSuccess:async()=>{closeDrawer(true);await refreshView()}});if(!result.ok)return;toast('Creator archived.')})}
async function cancelCollaborationRecord(record,button){const reason=prompt('Why is this collaboration being cancelled? This reason will be saved in its history.','Created by mistake');if(reason===null)return;if(!reason.trim())return toast('Enter a cancellation reason.');const checked=await runAction(button,'Checking shipment status',()=>related('shipments','collaboration_id',record.id),{buttonText:'Checking…'});if(!checked.ok)return;const sent=checked.value.some(row=>['Shipped','Delivered'].includes(row.status)),warning=sent?'A shipment is already marked as sent. Cancelling will preserve the shipment record but remove this collaboration from active metrics and queues. Continue?':'Cancel this collaboration? It will remain in history but leave active metrics, product counts, and fulfillment queues.';if(!confirm(warning))return;if(!confirmDiscardChanges(false))return;const result=await runAction(button,'Cancelling collaboration',()=>cancelCollaboration(record,reason),{buttonText:'Cancelling…',afterSuccess:async value=>{clearDraftGuard();state.drawer.record=value.record;await refreshView();await renderCollaborationDrawer()}});if(!result.ok)return;toast(result.value.activityWarning?'Collaboration cancelled. Activity history could not be recorded.':'Collaboration cancelled and retained in history.')}
async function deleteErroneousRecord(id,button){const lookup=await runAction(button,'Checking collaboration',()=>getOne('collaborations',id),{buttonText:'Checking…'});if(!lookup.ok)return;const record=lookup.value;if(!record)return toast('This collaboration no longer exists.');if(record.stage!=='Closed')return toast('Cancel the collaboration before permanently deleting it.');const code=record.collaboration_code||shortId(record.id,'CO'),reason=prompt(`Delete ${code} permanently?\n\nEnter the deletion reason to continue:`,'Created by mistake');if(reason===null)return;if(!reason.trim())return toast('Enter a deletion reason.');if(!confirmDiscardChanges(false))return;const result=await runAction(button,'Deleting erroneous record',()=>deleteErroneousCollaboration(record,reason),{buttonText:'Deleting…',afterSuccess:async()=>{clearDraftGuard();if(state.drawer?.record?.id===id)closeDrawer(true);await refreshView()}});if(!result.ok)return;toast(`${code} permanently deleted.`)}
async function saveDrawer(type){
  if(state.saving||state.actionBusy)return;
  const form=$('#drawerBody'),invalid=$(':invalid',form);clearDrawerError();
  if(invalid){invalid.reportValidity();return}
  const payload=Object.fromEntries(FormDataLike(form));
  if(payload.tags)payload.tags=payload.tags.split(',').map(x=>x.trim()).filter(Boolean);
  const before=state.drawer.record?.id?{...state.drawer.record}:null;
  if(type==='creator'&&!before){
    payload.instagram_handle=normalizeHandle(payload.instagram_handle,payload.instagram_profile_url);
    if(!payload.instagram_handle){showDrawerError('Enter an Instagram Handle before adding this creator.');return}
  }
  if(type==='collaboration'){
    if(!payload.creator_id){showDrawerError('Choose a creator before saving.');return}
    payload.is_repeat=payload.is_repeat==='true';if(payload.approved_budget==='')payload.approved_budget=null;
  }
  const button=$('.save-record'),result=await runAction(button,type==='creator'?'Saving creator':'Saving collaboration',async()=>{
    let record;
    if(type==='creator'&&!before){
      const{instagram_handle,instagram_profile_url,...creatorPayload}=payload;
      record=await createCreatorWithPrimaryAccount({creator:creatorPayload,account:{handle:instagram_handle,profile_url:instagram_profile_url}});
    }else record=await save(type==='creator'?'creators':'collaborations',{...state.drawer.record,...payload});
    let activityWarning=false;
    try{await logActivity({entityType:type,entityId:record.id,creatorId:type==='creator'?record.id:record.creator_id,collaborationId:type==='collaboration'?record.id:null,action:before?'Updated':'Created',before,after:record})}catch(error){activityWarning=true;console.error('Activity log failed after record save',error)}
    state.drawer.record=record;
    return{record,activityWarning};
  },{afterSuccess:async value=>{clearDraftGuard();if(type==='creator'){state.creatorPage=1;await loadCreators();await openCreator(value.record.id)}else{await refreshView();await openCollaboration(value.record.id)}}});
  if(!result.ok)return;
  toast(result.value.activityWarning?'Saved. Activity history could not be recorded.':before?'Changes saved.':type==='creator'?'Creator added at the top.':'Collaboration created.');
}

async function openCollaboration(id){const token=++state.request.detail;state.drawer=null;openDrawer('Collaboration','Loading…','');clearDrawerContent('Loading collaboration…');try{const c=await getOne('collaborations',id);if(token!==state.request.detail)return;if(!c)throw new Error('Collaboration not found.');if(c.creator_id&&!state.refs.creatorOptions.some(row=>row.id===c.creator_id)){const creator=await getOne('creators',c.creator_id);if(token!==state.request.detail)return;if(creator)state.refs.creatorOptions.push(creator)}state.drawer={type:'collaboration',record:c};state.drawerTab='overview';renderCollaborationDrawer()}catch(error){if(token===state.request.detail){clearDrawerContent('Unable to load this collaboration.');handleError(error)}}}
async function openCollaborationEditor(record){state.drawer={type:'collaboration',record};state.drawerTab='overview';openDrawer('Collaboration',record.collaboration_code||'New collaboration','');$('#drawerBody').innerHTML='<div class="empty-state">Loading creator choices…</div>';try{state.refs.creatorOptions=await creatorChoices();renderCollaborationDrawer(true)}catch(error){handleError(error)}}
async function renderCollaborationDrawer(editing=false){if(state.drawer?.type!=='collaboration')return;clearDraftGuard();const renderToken=++state.request.drawerRender,c=state.drawer.record,expectedId=c.id,expectedTab=state.drawerTab;openDrawer('Collaboration',c.collaboration_code||shortId(c.id,'CO')||'New collaboration',c.collaboration_name||'Confirmed work');renderTabs([['overview','Overview'],['products','Products'],['deliverables','Deliverables'],['shipments','Shipments'],['content','Publications & Assets'],['activity','Activity']],state.drawerTab,tab=>{state.drawerTab=tab;renderCollaborationDrawer(editing&&tab==='overview')});const body=$('#drawerBody');body.innerHTML='<div class="empty-state">Loading…</div>';$('#drawerFooter').innerHTML='';try{if(state.drawerTab==='overview')body.innerHTML=collaborationForm(c,editing);else if(!c.id)body.innerHTML='<div class="empty-state">Save the collaboration before adding related records.</div>';else await renderCollaborationRelations(c,state.drawerTab,body);if(renderToken!==state.request.drawerRender||!activeDrawer('collaboration',expectedId,expectedTab))return;renderDrawerFooter(c,editing,'collaboration');bindDrawerForms();if(editing&&state.drawerTab==='overview')beginDraftGuard('collaboration',body)}catch(error){if(renderToken===state.request.drawerRender&&activeDrawer('collaboration',expectedId,expectedTab)){body.innerHTML='<div class="empty-state">Unable to load this section.</div>';handleError(error)}}}
function collaborationForm(c,editing){const creatorOptions=(state.refs.creatorOptions||[]).map(x=>[x.id,`${x.display_name||x.nickname||'Unnamed'} · ${x.primary_handle?`@${x.primary_handle}`:x.creator_code||''}`]);return`<div class="drawer-section"><h3>${c.stage==='Closed'?'Closed collaboration':'Collaboration details'}</h3><div class="form-grid">${field('collaboration_name','Collaboration Name',c.collaboration_name,editing)}${selectField('creator_id','Creator',creatorOptions,c.creator_id,editing)}${selectField('campaign_id','Campaign',state.refs.campaigns.map(x=>[x.id,x.name]),c.campaign_id,editing)}${selectField('stage','Stage',COLLABORATION_STAGES,c.stage||COLLABORATION_STAGES[0],editing)}${field('type','Type',c.type||'Seeding',editing)}${selectField('owner_id','Owner',state.refs.owners.map(x=>[x.id,x.name]),c.owner_id,editing)}${field('start_date','Start Date',c.start_date,editing,'date')}${field('due_date','Due Date',c.due_date,editing,'date')}${selectField('rights_status','Rights Status',RIGHTS_STATUSES,c.rights_status,editing)}${selectField('payment_status','Payment Status',PAYMENT_STATUSES,c.payment_status,editing)}${field('approved_budget','Approved Budget',c.approved_budget,editing,'number')}${selectField('is_repeat','Repeat Collaboration',[['false','No'],['true','Yes']],String(Boolean(c.is_repeat)),editing,false)}${textarea('notes','Notes',c.notes,editing)}</div></div>`}
async function renderCollaborationRelations(c,tab,body){
  if(tab==='content')return renderContentRelations(c,body);
  if(tab==='products')return renderProductRelations(c,body);
  if(tab==='shipments'){
    const[rows,products]=await Promise.all([related('shipments','collaboration_id',c.id),related('collaboration_products','collaboration_id',c.id,'*,product:products(id,sku,name,category)')]);
    if(!activeDrawer('collaboration',c.id,tab))return;
    body.innerHTML=handoffBanner('Fulfillment handoff','1. Verify the packing list and full address. 2. Pack and ship exactly these items. 3. Add carrier and tracking, then mark the shipment Shipped.')+packingList(products)+relatedEditorSection('shipments','Shipments',rows,row=>row.shipment_code||shortId(row.id,'SH'),row=>`${row.status} · ${ownerName(row.owner_id)} · ${row.carrier||''} ${row.tracking_number||''}`,true);
    bindRelatedRows('shipments',c,rows);return;
  }
  const configs={deliverables:['deliverables','Deliverables',row=>row.type||'Format not agreed',row=>`${row.status} · ${row.platform||'Platform open'} · due ${date(row.due_at)}`],shipments:['shipments','Shipments',row=>row.shipment_code||shortId(row.id,'SH'),row=>`${row.status} · ${ownerName(row.owner_id)} · ${row.carrier||''} ${row.tracking_number||''}`],activity:['activity_logs','Activity',row=>row.action,row=>`${row.entity_type||''} · ${date(row.created_at)}`]};
  const[table,title,primary,secondary]=configs[tab],rows=await related(table,'collaboration_id',c.id,tab==='products'?'*,product:products(id,sku,name)':'*');
  if(!activeDrawer('collaboration',c.id,tab))return;
  const guidance=tab==='shipments'?handoffBanner('Fulfillment handoff','DM owner confirms the saved products and full address. Fulfillment teammate packs exactly that selection, then adds carrier and tracking here.') : '';
  body.innerHTML=guidance+relatedEditorSection(table,title,rows,primary,secondary,tab!=='activity');bindRelatedRows(table,c,rows);
}
async function renderProductRelations(c,body){
  const rows=await related('collaboration_products','collaboration_id',c.id,'*,product:products(id,sku,name,category)');
  if(!activeDrawer('collaboration',c.id,'products'))return;
  const selected=new Set(rows.map(row=>row.product_id)),groups=['Set','Scrunchie','Bandana','Necklace'];
  body.innerHTML=`${handoffBanner('Products to ship','DM owner checks every agreed item and saves once. Fulfillment teammate uses this saved list as the packing instruction.')}
    <div class="drawer-section product-picker"><div class="section-head"><div><h3>Final product selection</h3><p class="muted">Sets and individual items can be combined.</p></div><span id="productSelectionCount" class="status-pill">${selected.size} selected</span></div>
    <div class="product-groups">${groups.map(group=>{const products=state.refs.products.filter(product=>productCategory(product)===group);return`<section class="product-group"><p class="eyebrow">${group}s</p><div class="product-options">${products.map(product=>`<label class="product-option"><input type="checkbox" value="${attr(product.id)}" ${selected.has(product.id)?'checked':''}><span><strong>${esc(product.name)}</strong><small>${esc(product.sku||'')}</small></span></label>`).join('')||'<span class="muted">No products in this group.</span>'}</div></section>`}).join('')}</div>
    <div class="editor-actions"><button id="saveProductSelection" type="button">Save product selection</button></div></div>`;
  $$('.product-option input',body).forEach(input=>input.addEventListener('change',()=>{$('#productSelectionCount').textContent=`${$$('.product-option input:checked',body).length} selected`}));
  const saveButton=$('#saveProductSelection');saveButton.addEventListener('click',async()=>{const ids=$$('.product-option input:checked',body).map(input=>input.value),result=await runAction(saveButton,'Saving products',async()=>{await syncCollaborationProducts(c.id,ids,c.owner_id||null);return logActivitySafely({entityType:'collaboration_products',entityId:c.id,creatorId:c.creator_id,collaborationId:c.id,action:'Product selection updated',after:{product_ids:ids}})},{afterSuccess:()=>renderCollaborationDrawer()});if(!result.ok)return;toast(result.value?'Products saved. Activity history could not be recorded.':'Product selection saved.')});beginDraftGuard('product selection',body);
}
function productCategory(product){if(product.category)return product.category;const value=`${product.sku||''} ${product.name||''}`.toLowerCase();if(value.includes('set'))return'Set';if(value.includes('scr'))return'Scrunchie';if(value.includes('ban'))return'Bandana';return'Necklace'}
function handoffBanner(title,copy){return`<aside class="handoff-banner"><div><p class="eyebrow">Team handoff</p><strong>${esc(title)}</strong></div><p>${esc(copy)}</p></aside>`}
function packingList(rows){return`<section class="packing-list"><div><p class="eyebrow">Packing list</p><strong>${rows.length?`${rows.length} product${rows.length===1?'':'s'} confirmed`:'Products not confirmed'}</strong></div><div>${rows.length?rows.map(row=>`<span>${esc(row.product?.name||'Unknown product')} <b>×${row.quantity||1}</b></span>`).join(''):'<span class="muted">DM owner must save the final product selection before fulfillment.</span>'}</div></section>`}
async function renderContentRelations(c,body){
  const[publications,assets]=await Promise.all([related('publications','collaboration_id',c.id),related('assets','collaboration_id',c.id)]);
  if(!activeDrawer('collaboration',c.id,'content'))return;body.innerHTML=relatedEditorSection('publications','Published Links',publications,row=>`${row.platform||''} ${row.format||''}`,row=>`${row.status} · ${row.url||'No URL'}`,true)+relatedEditorSection('assets','Creator Assets',assets,row=>row.file_name||row.asset_type||'Asset',row=>row.external_url||row.storage_path||'No link',true);
  bindRelatedRows('publications',c,publications);bindRelatedRows('assets',c,assets);
}
function relatedEditorSection(table,title,rows,primary,secondary,canAdd){return`<div class="drawer-section"><div class="section-head"><h3>${title}</h3>${canAdd?`<button class="secondary compact" data-add-related="${table}" type="button">Add</button>`:''}</div>${rows.length?rows.map(row=>`<article class="related-item"><div><strong>${esc(primary(row)||'Untitled')}</strong><p>${esc(secondary(row)||'')}</p></div>${canAdd?`<button class="secondary compact" data-edit-related="${table}" data-id="${row.id}" type="button">Edit</button>`:''}</article>`).join(''):`<div class="empty-state">No ${title.toLowerCase()} yet.</div>`}</div>`}
function bindRelatedRows(table,c,rows){$$(`[data-add-related="${table}"]`).forEach(button=>button.addEventListener('click',()=>openRelatedEditor(table,c,{})));$$(`[data-edit-related="${table}"]`).forEach(button=>button.addEventListener('click',()=>openRelatedEditor(table,c,rows.find(row=>row.id===button.dataset.id)||{})))}
function openRelatedEditor(table,c,record){const body=$('#drawerBody'),title={collaboration_products:'Product',deliverables:'Deliverable',shipments:'Shipment',publications:'Published Link',assets:'Creator Asset'}[table],guidance=table==='deliverables'?handoffBanner('Deliverable details','Type and platform may stay open until the creator confirms them. Record only what is actually agreed.'):table==='shipments'?handoffBanner('Fulfillment teammate action','Verify the saved products and address, pack the order, then add carrier, tracking and shipment status here.'):'';clearDraftGuard();$('#drawerFooter').innerHTML='';body.innerHTML=`${guidance}<div class="drawer-section"><div class="section-head"><h3>${record.id?'Edit':'Add'} ${title}</h3><button id="cancelRelated" class="secondary compact" type="button">Cancel</button></div><div id="relatedForm" class="form-grid">${relatedFields(table,record)}</div><div class="editor-actions"><button id="saveRelated" type="button">Save ${title}</button>${record.id?'<button id="archiveRelated" class="secondary" type="button">Archive</button>':''}</div></div>`;$('#cancelRelated').addEventListener('click',()=>discardChangesThen(()=>renderCollaborationDrawer()));$('#saveRelated').addEventListener('click',()=>saveRelatedRecord(table,c,record,title));const archiveButton=$('#archiveRelated');archiveButton?.addEventListener('click',async()=>{if(!confirm(`Archive this ${title.toLowerCase()}?`))return;const result=await runAction(archiveButton,`Archiving ${title.toLowerCase()}`,async()=>{await archive(table,record.id);return logActivitySafely({entityType:table,entityId:record.id,creatorId:c.creator_id,collaborationId:c.id,action:'Archived',before:record})},{buttonText:'Archiving…',afterSuccess:()=>renderCollaborationDrawer()});if(!result.ok)return;toast(result.value?`${title} archived. Activity history could not be recorded.`:`${title} archived.`)});beginDraftGuard(title.toLowerCase(),$('#relatedForm'))}
function relatedFields(table,r){
  if(table==='collaboration_products')return`${selectField('product_id','Product',state.refs.products.map(x=>[x.id,`${x.name} · ${x.sku}`]),r.product_id,true)}${field('quantity','Quantity',r.quantity||1,true,'number')}${selectField('is_primary','Primary Product',[['false','No'],['true','Yes']],String(Boolean(r.is_primary)),true,false)}${textarea('notes','Notes',r.notes,true)}`;
  if(table==='deliverables')return`${field('type','Deliverable Type (optional)',r.type,true)}${field('platform','Platform (optional)',r.platform,true)}${field('quantity','Quantity',r.quantity||1,true,'number')}${selectField('status','Status',DELIVERABLE_STATUSES,r.status||'Pending',true,false)}${field('due_at','Due At',localDateTime(r.due_at),true,'datetime-local')}${field('brief_url','Brief URL',r.brief_url,true,'url')}${textarea('notes','Notes',r.notes,true)}`;
  if(table==='shipments')return`${selectField('owner_id','Fulfillment Owner',state.refs.owners.map(x=>[x.id,x.name]),r.owner_id,true)}${selectField('status','Status',SHIPMENT_STATUSES,r.status||'Draft',true,false)}${field('carrier','Carrier',r.carrier,true)}${field('service_level','Service Level',r.service_level,true)}${field('tracking_number','Tracking Number',r.tracking_number,true)}${field('tracking_url','Tracking URL',r.tracking_url,true,'url')}${field('shipped_at','Shipped At',localDateTime(r.shipped_at),true,'datetime-local')}${field('delivered_at','Delivered At',localDateTime(r.delivered_at),true,'datetime-local')}${textarea('address_snapshot','Full Shipping Address',typeof r.address_snapshot==='object'?r.address_snapshot?.full_address||JSON.stringify(r.address_snapshot):r.address_snapshot,true)}${textarea('exception_notes','Exception Notes',r.exception_notes,true)}`;
  if(table==='publications')return`${field('platform','Platform',r.platform||'Instagram',true)}${field('format','Format',r.format||'Post',true)}${field('url','Published URL',r.url,true,'url')}${selectField('status','Status',PUBLICATION_STATUSES,r.status||'Published',true,false)}${field('published_at','Published At',localDateTime(r.published_at),true,'datetime-local')}${field('views','Views',r.views,true,'number')}${field('likes','Likes',r.likes,true,'number')}${field('comments','Comments',r.comments,true,'number')}${field('shares','Shares',r.shares,true,'number')}${field('saves','Saves',r.saves,true,'number')}${textarea('notes','Performance Notes',r.notes,true)}`;
  return`${field('asset_type','Asset Type',r.asset_type||'Cloud Folder',true)}${field('file_name','Label',r.file_name,true)}${field('external_url','Drive / Asset URL',r.external_url,true,'url')}${selectField('rights_status','Rights Status',RIGHTS_STATUSES,r.rights_status,true)}${textarea('usage_notes','Usage Notes',r.usage_notes,true)}`;
}
async function saveRelatedRecord(table,c,before,title){const button=$('#saveRelated'),payload=Object.fromEntries(FormDataLike($('#relatedForm')));for(const key of ['quantity','views','likes','comments','shares','saves'])if(payload[key]!=='')payload[key]=Number(payload[key]);for(const key of ['is_primary'])if(key in payload)payload[key]=payload[key]==='true';for(const key of ['due_at','shipped_at','delivered_at','published_at'])if(payload[key]==='')payload[key]=null;if(table==='deliverables'){payload.type=payload.type||null;payload.platform=payload.platform||null}if(table==='shipments')payload.address_snapshot={full_address:payload.address_snapshot||'',source:'CRM v2'};const result=await runAction(button,`Saving ${title.toLowerCase()}`,async()=>{const saved=await save(table,{...before,...payload,collaboration_id:c.id,owner_id:payload.owner_id||before.owner_id||c.owner_id||null}),activityWarning=await logActivitySafely({entityType:table,entityId:saved.id,creatorId:c.creator_id,collaborationId:c.id,action:before.id?'Updated':'Created',before:before.id?before:null,after:saved});return{saved,activityWarning}},{afterSuccess:()=>renderCollaborationDrawer()});if(!result.ok)return;toast(result.value.activityWarning?'Saved. Activity history could not be recorded.':'Saved.')}
function openOutreachEditor(creatorId){const body=$('#drawerBody');clearDraftGuard();$('#drawerFooter').innerHTML='';body.innerHTML=`<div class="drawer-section"><div class="section-head"><h3>Add outreach touch</h3><button id="cancelOutreach" class="secondary compact" type="button">Cancel</button></div><div id="outreachForm" class="form-grid">${selectField('status','Status',OUTREACH_STATUSES,'Contacted',true)}${field('channel','Channel','Instagram DM',true)}${field('last_contact_at','Contacted At',new Date().toISOString().slice(0,16),true,'datetime-local')}${field('next_follow_up_at','Follow-up At','',true,'datetime-local')}${textarea('notes','Notes','',true)}</div><button id="saveOutreachBtn" type="button">Save outreach</button></div>`;$('#cancelOutreach').addEventListener('click',()=>discardChangesThen(()=>renderCreatorDrawer()));const button=$('#saveOutreachBtn');button.addEventListener('click',async()=>{const payload=Object.fromEntries(FormDataLike($('#outreachForm'))),result=await runAction(button,'Saving outreach',()=>save('outreach_records',{...payload,creator_id:creatorId,owner_id:state.drawer.record.owner_id}),{afterSuccess:()=>renderCreatorDrawer()});if(!result.ok)return;toast('Outreach saved.')});beginDraftGuard('outreach touch',$('#outreachForm'))}

async function applyBulkUpdate(){const patch={};if($('#bulkOwner').value)patch.owner_id=$('#bulkOwner').value;if($('#bulkFit').value)patch.fit_verdict=$('#bulkFit').value;if($('#bulkRelationship').value)patch.relationship_status=$('#bulkRelationship').value;if($('#bulkTags').value)patch.tags=$('#bulkTags').value.split(',').map(x=>x.trim()).filter(Boolean);if(!Object.keys(patch).length)return toast('Choose at least one field.');const button=$('#applyBulkBtn'),result=await runAction(button,`Updating ${state.creatorSelection.size} creators`,()=>bulkUpdateCreators([...state.creatorSelection],patch),{inlineError:false,buttonText:'Applying…',afterSuccess:async()=>{$('#bulkDialog').close();state.creatorSelection.clear();await loadCreators()}});if(!result.ok)return;toast('Bulk update complete.')}
function draftSnapshot(root){return root?JSON.stringify($$('input,select,textarea',root).map((control,index)=>[control.name||control.id||`${control.tagName}:${index}`,control.type||control.tagName,['checkbox','radio'].includes(control.type)?control.checked:control.value])):''}
function beginDraftGuard(label,root){clearDraftGuard();if(!root)return;const draft={label,root,baseline:draftSnapshot(root)};draft.listener=()=>refreshDraftIndicator();root.addEventListener('input',draft.listener);root.addEventListener('change',draft.listener);state.draft=draft;refreshDraftIndicator()}
function clearDraftGuard(){const draft=state.draft;if(draft?.root&&draft.listener){draft.root.removeEventListener('input',draft.listener);draft.root.removeEventListener('change',draft.listener)}state.draft=null;$('#drawerDraftStatus')?.classList.add('hidden')}
function hasUnsavedChanges(){const draft=state.draft;return Boolean(draft?.root?.isConnected&&draftSnapshot(draft.root)!==draft.baseline)}
function refreshDraftIndicator(){const indicator=$('#drawerDraftStatus');if(indicator)indicator.classList.toggle('hidden',!hasUnsavedChanges())}
function confirmDiscardChanges(clear=true){if(!hasUnsavedChanges()){if(clear)clearDraftGuard();return true}if(!confirm(`You have unsaved changes in this ${state.draft?.label||'record'}. Discard them?`))return false;if(clear)clearDraftGuard();return true}
function discardChangesThen(action){if(!confirmDiscardChanges())return false;return action()}
function warnBeforeUnload(event){if(!hasUnsavedChanges())return;event.preventDefault();event.returnValue=''}
function openDrawer(eyebrow,title,subtitle){$('#drawerEyebrow').textContent=eyebrow;$('#drawerTitle').textContent=title;$('#drawerSubtitle').textContent=subtitle;$('#drawer').classList.add('open');$('#drawer').setAttribute('aria-hidden','false')}
function clearDrawerContent(message='Loading…'){$('#drawerTabs').innerHTML='';$('#drawerBody').innerHTML=`<div class="empty-state">${esc(message)}</div>`;$('#drawerFooter').innerHTML=''}
function closeDrawer(force=false){if(!force&&!confirmDiscardChanges())return false;clearDraftGuard();++state.request.detail;++state.request.drawerRender;$('#drawer').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true');state.drawer=null;clearDrawerContent('Select a record to view details.');return true}
function renderTabs(tabs,active,onClick){$('#drawerTabs').innerHTML=tabs.map(([id,label])=>`<button class="${id===active?'active':''}" data-tab="${id}" type="button">${label}</button>`).join('');$$('#drawerTabs button').forEach(button=>button.addEventListener('click',()=>{const tab=button.dataset.tab;if(tab===active)return;discardChangesThen(()=>onClick(tab))}))}
function bindDrawerForms(){}
function relationSection(title,rows,primary,secondary){return`<div class="drawer-section"><h3>${title}</h3>${rows.length?rows.map(row=>`<article class="related-item"><div><strong>${esc(primary(row)||'Untitled')}</strong><p>${esc(secondary(row)||'')}</p></div></article>`).join(''):`<div class="empty-state">No ${title.toLowerCase()} yet.</div>`}</div>`}
function field(name,label,value,editing,type='text',required=false){return`<label>${label}${required?' *':''}<input name="${name}" type="${type}" value="${attr(value)}" ${editing?'':'disabled'} ${required?'required aria-required="true"':''}></label>`}
function textarea(name,label,value,editing){return`<label class="wide">${label}<textarea name="${name}" rows="3" ${editing?'':'disabled'}>${esc(value||'')}</textarea></label>`}
function selectField(name,label,options,value,editing,includeBlank=true){const normalized=options.map(x=>Array.isArray(x)?x:[x,x]);if(value&&!normalized.some(([id])=>String(id)===String(value)))normalized.unshift([value,value]);return`<label>${label}<select name="${name}" ${editing?'':'disabled'}>${includeBlank?'<option value="">Select</option>':''}${normalized.map(([id,text])=>`<option value="${attr(id)}" ${String(id)===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`}
function setOptions(element,options){if(!element)return;const normalized=options.map(x=>Array.isArray(x)?x:[x,x]);element.innerHTML='<option value="">All</option>'+normalized.map(([id,text])=>`<option value="${attr(id)}">${esc(text)}</option>`).join('')}
function ownerName(id){return state.refs.owners.find(x=>x.id===id)?.name||id||'Unassigned'}
function creatorProfileUrl(savedUrl,handle,platform='Instagram'){const direct=String(savedUrl||'').trim();if(/^https?:\/\//i.test(direct))return direct;const cleanHandle=String(handle||'').trim().replace(/^@/,'');return cleanHandle&&String(platform||'Instagram').toLowerCase().includes('instagram')?`https://www.instagram.com/${encodeURIComponent(cleanHandle)}/`:''}
function profileAction(url){return url?`<a class="profile-link" href="${attr(url)}" target="_blank" rel="noopener noreferrer" title="Open creator Instagram profile" aria-label="Open creator Instagram profile">Open IG</a>`:''}
function bindProfileLinks(root){$$('.profile-link',root).forEach(link=>{link.addEventListener('click',event=>event.stopPropagation());link.addEventListener('dblclick',event=>event.stopPropagation())})}
function activeDrawer(type,id,tab){return state.drawer?.type===type&&state.drawer.record?.id===id&&state.drawerTab===tab}
function shortId(id,prefix){if(!id)return'';return`${prefix}-${String(id).replaceAll('-','').slice(-6).toUpperCase()}`}
function date(value){if(!value)return'—';const parsed=new Date(value);return Number.isNaN(parsed.valueOf())?esc(value):parsed.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'})}
function localDateTime(value){if(!value)return'';const parsed=new Date(value);return Number.isNaN(parsed.valueOf())?'':new Date(parsed.getTime()-parsed.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function esc(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function attr(value){return esc(value).replaceAll('`','&#96;')}
function setStatus(text){$('#saveStatus').textContent=text}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function message(error){try{const parsed=JSON.parse(error.message);return parsed.message||parsed.error_description||error.message}catch{return error.message||String(error)}}
function clearDrawerError(){$('#drawerError')?.remove()}
function showDrawerError(text){clearDrawerError();const node=document.createElement('p');node.id='drawerError';node.className='form-error';node.setAttribute('role','alert');node.textContent=text;const body=$('#drawerBody');body.prepend(node);body.scrollTop=0}
function saveErrorMessage(error){const text=message(error);if(/duplicate key|already exists/i.test(text))return text.includes('already in Creator database')?text:'This record already exists. Review its identifying fields and try again.';if(/invalid input syntax for type uuid/i.test(text))return'One of the selected records is invalid. Clear the optional selection and try again.';return text}
async function runAction(button,statusText,work,{buttonText='Saving…',inlineError=true,afterSuccess=null}={}){if(state.actionBusy||state.saving||button?.disabled)return{ok:false,busy:true};const originalLabel=button?.textContent||'',scope=button?.closest('#drawer,dialog'),controls=scope?$$('button,input,select,textarea',scope):button?[button]:[],disabledStates=new Map(controls.map(control=>[control,control.disabled]));state.actionBusy=true;scope?.classList.add('action-busy');scope?.setAttribute('aria-busy','true');controls.forEach(control=>control.disabled=true);if(button)button.textContent=buttonText;if(inlineError&&state.drawer&&$('#drawer').classList.contains('open'))clearDrawerError();setStatus(statusText);try{const value=await work();if(afterSuccess)try{await afterSuccess(value)}catch(error){const friendly='The action was saved, but the latest view could not be refreshed. Do not repeat it; use Refresh.';if(inlineError&&state.drawer&&$('#drawer').classList.contains('open'))showDrawerError(friendly);handleError(error,friendly);return{ok:false,completed:true,value,error}}setStatus('Ready');return{ok:true,value}}catch(error){const friendly=saveErrorMessage(error);if(inlineError&&state.drawer&&$('#drawer').classList.contains('open'))showDrawerError(friendly);handleError(error,friendly);return{ok:false,error}}finally{state.actionBusy=false;scope?.classList.remove('action-busy');scope?.removeAttribute('aria-busy');disabledStates.forEach((disabled,control)=>{if(control.isConnected)control.disabled=disabled});if(button?.isConnected)button.textContent=originalLabel}}
async function logActivitySafely(entry){try{await logActivity(entry);return false}catch(error){console.error('Activity log failed after the main action succeeded',error);return true}}
function handleError(error,displayMessage=message(error)){console.error(error);setStatus('Error');toast(displayMessage);if(message(error).includes('session expired'))location.reload()}
